// ============================================================
// DIMENSION: is_valid-predicate  -- definitive spec after falsification
// Binary: /workspace/dataset/test15_executable
// Contract: argv = [scheme, host, port, path, query, fragment]
// ============================================================

fn main(args: Vec<String>) -> ! {
    // --- STEP 0: argc gate (observed, out of the stated contract) ---
    // Fewer than 6 user args -> exit(1) with EMPTY stdout and EMPTY stderr.
    //   evidence: 0,1,2,3,4,5 args -> rc=1, out=[]
    // More than 6 -> extra args ignored entirely.
    //   evidence: ("http","example.com","80","/","","","EXTRA0") -> same 8 lines, last=1
    if args.len() < 6 { exit(1); }
    let (scheme_in, host_in, port_in, path_in, query_in, frag_in) =
        (args[0], args[1], args[2], args[3], args[4], args[5]);

    // --- STEP 1: port parse. THIS RUNS BEFORE ANY OUTPUT. ---
    // Semantics of C++ std::stoi on the raw bytes:
    //   skip leading isspace(): ' ' \t \n \v \f \r
    //   optional single '+' or '-' IMMEDIATELY before the first digit
    //   consume ASCII decimal digits [0-9]+ (non-ASCII digits do NOT count)
    //   ignore all trailing bytes
    // If zero digits were consumed -> std::invalid_argument
    // If the value does not fit in i32 -> std::out_of_range
    // Either exception is UNCAUGHT: process aborts.
    //   observable: stdout is EXACTLY 0 bytes, exit code 134 (SIGABRT, core dumped),
    //   stderr = "terminate called after throwing an instance of 'std::invalid_argument'\n  what():  stoi"
    //            (or 'std::out_of_range' for overflow)
    //   THERE IS NO is_valid OUTPUT IN THIS CASE. It is not a validity-0 path.
    // Aborting examples (verified against all 4 host/path combos):
    //   "", " ", "  ", "abc", "abc80", "+", "-", "++80", "+-80", "-+80", ".5",
    //   "INF", "inf", "nan", "NaN", "-  80", "\u{663}", "\u{FF12}", "\u{1D7D6}",
    //   "2147483648", "-2147483649"
    // Parsing examples: "80abc"->80, "080"->80, "00"->0, "-0"->0, "0x50"->0,
    //   "0X50"->0, "1e3"->1, "3.14"->3, "1,000"->1, "1 2"->1, "1_0"->1,
    //   " 80"->80, "\t80"->80, "\n80"->80, "\v80"->80, "\f80"->80, "\r80"->80,
    //   "80 "->80, "80\v"->80, "  -80"->-80, "2147483647"->2147483647,
    //   "-2147483648"->-2147483648
    let n: i32 = stoi_or_abort(port_in);

    // --- STEP 2: field storage (side effects; none of these change validity) ---
    let scheme = ascii_lowercase(scheme_in);   // byte-wise: 'A'..='Z' -> +32; ALL other bytes
                                               // untouched. NOT locale-aware: LC_ALL=tr_TR.UTF-8
                                               // still maps "HTTPI"->"httpi". "CAF\xC3\x89" -> "caf\xC3\x89".
    let host = host_in;                        // stored VERBATIM: no trim, no case fold, no validation.
    let port = if n >= 0 && n <= 65535 { n } else { -1 };  // 65535 kept; 65536 -> -1; any negative -> -1
    let path = if path_in.is_empty() { "".to_string() }
               else if path_in.starts_with('/') { path_in }
               else { format!("/{}", path_in) };
    let query = query_in;                      // verbatim
    let fragment = frag_in;                    // verbatim

    // --- STEP 3: THE PREDICATE (the whole dimension) ---
    // is_valid() == !host.is_empty() || !path.is_empty()
    // Equivalently: !(host.is_empty() && path.is_empty())
    //               host.len() + path.len() > 0
    // "empty" means ZERO BYTES. Nothing else counts:
    //   - no trimming: host " " / "\t" / "\n" / 0x01 / 0x7F  => VALID
    //   - no charset/DNS/IP/length check: every one of the 255 non-NUL byte values,
    //     invalid UTF-8 (0xFF, 0xC0 0x80), 131071-byte hosts => VALID
    //   - scheme is IGNORED (including "file", "mailto", "data", "about", "javascript")
    //   - port is IGNORED (including 0, -1, 65536, and clamped-to--1 values)
    //   - query and fragment are IGNORED (including 10000-byte ones)
    // Because a non-empty argv host/path can never normalize to empty, computing this
    // on the raw argv values or on the stored values is provably identical.
    let is_valid = !host.is_empty() || !path.is_empty();

    // --- STEP 4: output, 8 println!'s in this exact order ---
    // 1 scheme(), 2 host(), 3 port() as decimal i32, 4 path(), 5 query(),
    // 6 fragment(), 7 to_string(), 8 is_valid() printed as "1" or "0"
    //   (integer form, NOT "true"/"false"; std::boolalpha is not used)
    // CAUTION for test harnesses: if any field contains LF the output has MORE than
    // 8 lines; is_valid is always the LAST line.
    //   ("http","a\nb","80","","","") -> 10 lines, last = "1"
    exit(0);
}

// ============================================================
// GOLDEN CASES (exact literals; all re-run and verified)
// ============================================================
// ("http","example.com","80","/","","")  -> http|example.com|80|/|||http://example.com:80/|1
// ("http","example.com","-1","","","")   -> http|example.com|-1||||http://example.com|1
// ("http","example.com","0","/","","")   -> ...|http://example.com:0/|1
// ("http","","80","/","","")             -> http||80|/|||http://:80/|1
// ("http","","80","","","")              -> http||80||||http://:80|0     <-- non-empty to_string, INVALID
// ("http","","-1","","","")              -> http||-1||||http://|0
// ("http","","80","","qqq","fff")        -> http||80||qqq|fff|http://:80?qqq#fff|0
// ("","example.com","80","/","","")      -> |example.com|80|/|||/|1       <-- authority vanishes, valid
// ("","a","80","","","")                 -> |a|80|||||1                  <-- EMPTY to_string, VALID
// ("","a","80","","q","f")               -> |a|80||q|f|?q#f|1
// ("","","0","","","")                   -> ||0|||||0
// ("",""," 80"," ","","")  [path=space]  -> ||80|/ |||/ |1
// ("",""," 80","","","")   [all empty]   -> ||80|||||0
// ("file","","80","","","")              -> file||80||||file://:80|0     <-- no special schemes
// ("HTTP","EXAMPLE.COM","80","/","","")  -> http|EXAMPLE.COM|80|/|||http://EXAMPLE.COM:80/|1
// ("http","example.com","abc","/","","") -> stdout EMPTY, rc=134, stderr stoi invalid_argument
//
// TRUTH TABLE FOR is_valid (exhaustive over the only two operands):
//   host=""      path=""      -> 0
//   host=""      path!=""     -> 1
//   host!=""     path=""      -> 1
//   host!=""     path!=""     -> 1
